 '<section class="fl-settings-section"><h4>Reader</h4><div class="fl-choices" role="group" aria-label="Reading layout">'+[['scroll','Scroll','list'],['paged','Paged','book'],['spread','Two pages','gallery']].map(([key,label,symbol])=>'<button class="fl-choice" data-fl="readingmode" data-mode="'+key+'" aria-pressed="'+((flState.readingMode||'scroll')===key)+'">'+icon(symbol)+label+'</button>').join('')+'</div>'+
 flPrecision('fl-font-size','Text size','fontSize',14,26,1,' px')+flPrecision('fl-line-height','Line spacing','lineHeight',1.2,2.4,.1,'×')+flPrecision('fl-speech-rate','Speech rate','speechRate',.5,2,.1,'×')+
 '<div class="fl-setting-row"><div><strong>Tap zones</strong><p>Choose a preset, then adjust each region.</p></div><button class="quiet" data-fl="tap">Customize '+icon('arrow')+'</button></div><div class="fl-setting-row"><div><strong>Reader toolbar</strong><p>Your frequent actions, in your order.</p></div><button class="quiet" data-fl="toolbar">Arrange '+icon('arrow')+'</button></div></section>'+
 '<section class="fl-settings-section"><h4>Comfort & accessibility</h4><label class="fl-setting-row"><div><strong>Keep screen awake</strong><p>Preview preference only.</p></div><input class="switch" type="checkbox" role="switch" data-fl-setting="awake" aria-label="Keep preview screen awake" '+(flState.awake?'checked':'')+'></label><label class="fl-setting-row"><div><strong>Reduce motion</strong><p>System preference takes priority.</p></div><input class="switch" type="checkbox" role="switch" data-fl-setting="reduce" aria-label="Reduce preview motion" '+(SeaMotion.reduced()?'checked':'')+' '+(motionPreference.matches?'disabled':'')+'></label></section><p class="fl-footnote">Typography and layout controls are design samples. Native ports will retain Dynamic Type, gestures and OS presentation.</p>';
