function flRenderSettings(){flContent.innerHTML='<div class="fl-page-title"><div><p class="eyebrow">A place that feels familiar</p><h3 id="folder-title" tabindex="-1">Settings</h3><p class="fl-page-subtitle">A few thoughtful choices. Nothing in your way.</p></div></div>'+flSettingsMarkup();flBindSettings(flContent);}
