 if(kind==='locations')body=[['home','home','On this device','Local folders & your everyday files'],['drive','cloud','Google Drive','A connected location · sample only'],['nas','server','Studio NAS','Private network collection · sample only']].map(([id,symbol,name,detail])=>'<button class="fl-sheet-location" data-fl="chooselocation" data-folder="'+id+'"><span class="fl-file-icon glass">'+icon(symbol)+'</span><span><strong>'+name+'</strong><small>'+detail+'</small></span>'+icon('arrow')+'</button>').join('')+'<p class="fl-footnote">No sign-in or network connection is made in this preview.</p>';
